CREATE TABLE IF NOT EXISTS approval_thresholds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),min_amount_minor BIGINT NOT NULL CHECK(min_amount_minor>=0),max_amount_minor BIGINT NOT NULL,currency TEXT NOT NULL,required_approvals INTEGER NOT NULL CHECK(required_approvals>=1),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),CHECK(max_amount_minor>min_amount_minor));
CREATE TABLE IF NOT EXISTS authorization_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),release_request_id UUID NOT NULL,requested_by UUID NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,required_approvals INTEGER NOT NULL,status TEXT NOT NULL CHECK(status IN('PENDING','AUTHORIZED','REJECTED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),authorized_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS financial_approval_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),authorization_id UUID NOT NULL REFERENCES authorization_decisions(id),approver_id UUID NOT NULL,decision TEXT NOT NULL CHECK(decision IN('APPROVE','REJECT')),rationale TEXT NOT NULL,decided_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(authorization_id,approver_id));
CREATE TABLE IF NOT EXISTS payment_instructions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),release_request_id UUID NOT NULL,provider_key TEXT NOT NULL,idempotency_key TEXT NOT NULL,beneficiary_reference TEXT NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','SUBMITTED','SETTLED','FAILED','REVERSED')),provider_reference TEXT,attempts INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),submitted_at TIMESTAMPTZ,settled_at TIMESTAMPTZ,UNIQUE(workspace_id,idempotency_key));
CREATE TABLE IF NOT EXISTS ledger_entries(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),payment_instruction_id UUID NOT NULL REFERENCES payment_instructions(id),entry_type TEXT NOT NULL CHECK(entry_type IN('DEBIT','CREDIT')),amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,description TEXT NOT NULL,recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS reconciliation_records(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),payment_instruction_id UUID NOT NULL REFERENCES payment_instructions(id),provider_statement_reference TEXT NOT NULL,provider_reported_amount_minor BIGINT NOT NULL,recorded_amount_minor BIGINT NOT NULL,matched BOOLEAN NOT NULL,exception_reason TEXT,reconciled_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS disputes(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),release_request_id UUID NOT NULL,kind TEXT NOT NULL CHECK(kind IN('PAYMENT_DISPUTE','CLAIM','APPEAL')),description TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('OPEN','MEDIATION','DECIDED','APPEALED','CLOSED')),raised_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dispute_evidence(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),dispute_id UUID NOT NULL REFERENCES disputes(id),reference TEXT NOT NULL,description TEXT NOT NULL,submitted_by UUID NOT NULL,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dispute_positions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),dispute_id UUID NOT NULL REFERENCES disputes(id),party_id UUID NOT NULL,position TEXT NOT NULL,submitted_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dispute_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),dispute_id UUID NOT NULL REFERENCES disputes(id),decision TEXT NOT NULL CHECK(decision IN('UPHELD','REJECTED','PARTIAL')),rationale TEXT NOT NULL,decided_by UUID NOT NULL,decided_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dispute_holds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),dispute_id UUID NOT NULL REFERENCES disputes(id),release_request_id UUID NOT NULL,active BOOLEAN NOT NULL,placed_at TIMESTAMPTZ NOT NULL DEFAULT now(),released_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS final_settlement_accounts(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,total_entitlement_amount_minor BIGINT NOT NULL CHECK(total_entitlement_amount_minor>0),total_settled_amount_minor BIGINT NOT NULL CHECK(total_settled_amount_minor>=0),outstanding_amount_minor BIGINT NOT NULL CHECK(outstanding_amount_minor>=0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','CLOSED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),closed_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS financial_closure_certificates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,final_settlement_account_id UUID NOT NULL REFERENCES final_settlement_accounts(id),canonical_hash TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('ISSUED','REVOKED')),issued_by UUID NOT NULL,issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS authorization_decisions_release_request_idx ON authorization_decisions(workspace_id,release_request_id);CREATE INDEX IF NOT EXISTS payment_instructions_release_request_idx ON payment_instructions(workspace_id,release_request_id);CREATE INDEX IF NOT EXISTS ledger_entries_instruction_idx ON ledger_entries(workspace_id,payment_instruction_id);CREATE INDEX IF NOT EXISTS reconciliation_records_matched_idx ON reconciliation_records(workspace_id,matched);CREATE INDEX IF NOT EXISTS disputes_release_request_idx ON disputes(workspace_id,release_request_id,status);CREATE INDEX IF NOT EXISTS dispute_holds_release_request_active_idx ON dispute_holds(workspace_id,release_request_id,active);CREATE INDEX IF NOT EXISTS final_settlement_accounts_milestone_idx ON final_settlement_accounts(workspace_id,milestone_id);
ALTER TABLE approval_thresholds ENABLE ROW LEVEL SECURITY;ALTER TABLE authorization_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE financial_approval_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE payment_instructions ENABLE ROW LEVEL SECURITY;ALTER TABLE ledger_entries ENABLE ROW LEVEL SECURITY;ALTER TABLE reconciliation_records ENABLE ROW LEVEL SECURITY;ALTER TABLE disputes ENABLE ROW LEVEL SECURITY;ALTER TABLE dispute_evidence ENABLE ROW LEVEL SECURITY;ALTER TABLE dispute_positions ENABLE ROW LEVEL SECURITY;ALTER TABLE dispute_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE dispute_holds ENABLE ROW LEVEL SECURITY;ALTER TABLE final_settlement_accounts ENABLE ROW LEVEL SECURITY;ALTER TABLE financial_closure_certificates ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['approval_thresholds','authorization_decisions','financial_approval_decisions','payment_instructions','ledger_entries','reconciliation_records','disputes','dispute_evidence','dispute_positions','dispute_decisions','dispute_holds','final_settlement_accounts','financial_closure_certificates'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['approval_thresholds','authorization_decisions','financial_approval_decisions','ledger_entries','reconciliation_records','dispute_evidence','dispute_positions','dispute_decisions','dispute_holds','final_settlement_accounts','financial_closure_certificates'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
